/**
 * Use to inject a web component slot to bypass the Svelte compiler from messing with it.
 * As of Svelte 4, named slots are getting compiled away on our web components.
 * Unnamed slots still work, so this function is not needed for those.
 *
 * TODO in the future this could be expanded to allow an "onSlotChange" binding by adding an
 * additional-svelte-typings.d.ts file to the project.
 *
 * @param name the name of the slot
 * @returns
 */
export declare const getNamedSlot: (name: string) => string;
